// Writes the site icons (cut from Mashudu's Sienna Shea Butter logo, public/sienna-logo.jpg)
// and site.webmanifest into public/ before each build. Icons are stored as base64 here
// because they were committed through a text-only API.
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const publicDir = join(dirname(fileURLToPath(import.meta.url)), "..", "public");
mkdirSync(publicDir, { recursive: true });

const icons = {
  "favicon.ico": "",
  "favicon-32x32.png": "",
  "favicon-48x48.png": "",
  "apple-touch-icon.png": "",
  "icon-192x192.png": "",
  "icon-512x512.png": ""
};

for (const [name, b64] of Object.entries(icons)) {
  writeFileSync(join(publicDir, name), Buffer.from(b64, "base64"));
}

const manifest = {
  "name": "Sienna Shea Butter",
  "short_name": "Sienna",
  "icons": [
    {
      "src": "/icon-192x192.png",
      "sizes": "192x192",
      "type": "image/png"
    },
    {
      "src": "/icon-512x512.png",
      "sizes": "512x512",
      "type": "image/png"
    }
  ],
  "theme_color": "#f2f0e3",
  "background_color": "#f2f0e3",
  "display": "browser",
  "start_url": "/"
};
writeFileSync(join(publicDir, "site.webmanifest"), JSON.stringify(manifest, null, 2) + "\n");
console.log(`write-icons: wrote ${Object.keys(icons).length} icons and site.webmanifest`);
